/**
 * Runtime state information about the VR Location Scouting Viewfinder
 *
 * bpy.types.XrViewfinderState
 */
export interface XrViewfinderState extends R.bpy_struct {
  /** Last known location of the viewfinder in world space Default: (0.0, 0.0, 0.0). */
  get location(): H.Remote<M.Vector>;
  /** Last known orientation of the viewfinder in world space Default: (0.0, 0.0, 0.0, 0.0). */
  get orientation(): H.Remote<M.Quaternion>;
  /** Enable viewfinder capture depth of field Default: False. */
  get capture_dof_enabled(): H.Ref<boolean>;
  set capture_dof_enabled(v: H.In<boolean>);
  /** Viewfinder capture focal length value in millimeters Default: 0.0. */
  get capture_lens_focal(): H.Ref<number>;
  set capture_lens_focal(v: H.In<number>);
  /** Viewfinder capture distance to the focus point for depth of field Default: 0.0. */
  get capture_dof_distance(): H.Ref<number>;
  set capture_dof_distance(v: H.In<number>);
  /** Viewfinder capture f-stop ratio Default: 0.0. */
  get capture_dof_fstop(): H.Ref<number>;
  set capture_dof_fstop(v: H.In<number>);
  /** Display active capture in space when in Viewfinder Playback mode Default: False. */
  get playback_show_active_capture_in_space_enabled(): H.Ref<boolean>;
  set playback_show_active_capture_in_space_enabled(v: H.In<boolean>);
  /**
   * Active viewfinder mode, live or playback Default: 'LIVE'.
   * - `LIVE`: Live Mode (Capture a shot using the viewfinder)
   * - `PLAYBACK`: Playback Mode (Preview and playback captured shots in the viewfinder)
   * - `CONFIRM`: Confirmation Mode (Confirm user action)
   */
  get active_mode(): H.Ref<"LIVE" | "PLAYBACK" | "CONFIRM">;
  set active_mode(v: H.In<"LIVE" | "PLAYBACK" | "CONFIRM">);
  /**
   * Active viewfinder live action Default: 'LENS'.
   * - `LENS`: Focal Length Control
   * - `DOF`: Toggle Depth of Field
   * - `FOCUS`: Set Focus Point
   * - `APERTURE`: Aperture Control
   */
  get active_action_live(): H.Ref<"LENS" | "DOF" | "FOCUS" | "APERTURE">;
  set active_action_live(v: H.In<"LENS" | "DOF" | "FOCUS" | "APERTURE">);
  /**
   * Active viewfinder playback action Default: 'BROWSE'.
   * - `BROWSE`: Browse captured shots
   * - `PREVIEW`: Preview selected shot in space
   * - `DELETE`: Delete selected shot
   */
  get active_action_playback(): H.Ref<"BROWSE" | "PREVIEW" | "DELETE">;
  set active_action_playback(v: H.In<"BROWSE" | "PREVIEW" | "DELETE">);
  /**
   * Active viewfinder confirm action Default: 'CONFIRM'.
   * - `CANCEL`: Cancel
   * - `CONFIRM`: Confirm
   */
  get active_action_confirm(): H.Ref<"CANCEL" | "CONFIRM">;
  set active_action_confirm(v: H.In<"CANCEL" | "CONFIRM">);
  /** Trigger the Viewfinder flash to indicate a shot was captured */
  trigger_flash(): H.Ref<void>;
  /**
   * Blink the Viewfinder crosshair to indicate whether a focus action hit a target
   * @param hit_success True to blink the success color, False to blink the miss color
   */
  trigger_focus_indicator(hit_success: H.In<boolean>): H.Ref<void>;
  /**
   * Blink the Viewfinder crosshair to indicate whether a focus action hit a target
   * @param hit_success True to blink the success color, False to blink the miss color
   */
  trigger_focus_indicator(kw: {
    /** True to blink the success color, False to blink the miss color */
    hit_success: H.In<boolean>;
  }): H.Ref<void>;
  /** Reset the Viewfinder continuous view smoothing */
  reset_view_smoothing(): H.Ref<void>;
}
